final class ContextSignedPendingMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean bad=false;try{a.run();}catch(Exception expected){bad=true;}require(bad,why);}
 static ContextSignedCandidateInspection.Limits limits(){return ContextSignedCandidateLeaseMatrix.limits();}
 static void create(Path d,String n,String text)throws Exception{ContextNativeCandidateLeaseMatrix.create(d,n,text);}
 static ContextProductionInventory inventory(Fixture f,Mind m)throws Exception{return ContextNativePendingInspectionMatrix.inventory(f,m);}
 static void yes(Result r){require(r.status==Status.QUIESCENT_SUPPLIED&&r.proposed!=null&&r.oppositions.isEmpty(),r.phase+": "+r.reason);}
 static void exact(Fixture f,Result r)throws Exception{Map<UUID,View> all=new LinkedHashMap<>();for(CutView c:r.foreign)for(View v:c.members)require(all.put(v.context,v)==null,"physical member exactly once");require(all.size()==f.db.dmzTopology().size(),"all actual physical members");for(ContextConnection c:f.db.dmzTopology()){ContextProductionInventory i=ContextProductionInventory.inspect(c.layer(),c.getTarget().getContextId(),c.getTarget().getRevision(),false,c.getInitialization(),64);View v=all.get(i.context);require(v!=null&&v.revision==i.revision&&v.fingerprint.equals(i.fingerprint)&&v.initialization.equals(i.initialization),"exact original initialized member pin, no routing alias");}}
 static void positive()throws Exception{Path d=Files.createTempDirectory("signed-pending-");create(d,"A","!$u seed(u)&&~blocked(u);");create(d,"B","!b(1);");for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(d,"X"+reverse)){require(f.mind.compile("!anchor(1);",null,false),"parent anchor");f.db.connectContext(reverse?"B":"A");f.db.connectContext(reverse?"A":"B");State parent=new State(f);Mind child=new Mind(f.mind);try{require(child.compile("!local(7); !@u seed(u)->~blocked(u);",null,false),"actual whole two-assertion batch");String fp=inventory(f,child).fingerprint;Result r=f.db.inspectSignedPendingProduction(child,limits());yes(r);require(r.proposed.fingerprint.equals(fp)&&inventory(f,child).primary.size()==3,"actual prepared child once, no staging or dropped batch assertion");exact(f,r);parent.unchanged(f);require(fp.equals(inventory(f,child).fingerprint),"whole pending inventory unchanged");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){ContextSignedPendingGuard.Result ready=lease.qualifySigned(limits());require(ready.status==ContextSignedPendingGuard.Status.SCOPED_QUIESCENT&&ready.evidence==null,"scoped quiescence supplies NO admission/refutation capability");}}finally{f.mind.release(child);}require(f.db.getRevision()==parent.revision&&inventory(f,f.mind).fingerprint.equals(parent.fingerprint),"release preserves physical parent");
 State beforeClash=new State(f);Mind clash=new Mind(f.mind);try{require(clash.compile("!@u seed(u)->blocked(u);",null,false),"actual signed conflicting child");Result r=f.db.inspectSignedPendingProduction(clash,limits());require(r.status==Status.REFUTED&&!r.oppositions.isEmpty(),r.phase+": "+r.reason);exact(f,r);for(Opposition o:r.oppositions)require(o.initial&&o.depth==2&&o.sources.size()==2&&o.sources.stream().filter(s->s.localX).allMatch(s->s.context.equals(f.db.getContextId())&&s.view.equals("inventory:"+r.proposed.fingerprint)),"actual whole child Source, no candidate rebasing");beforeClash.unchanged(f);}finally{f.mind.release(clash);}}
 System.out.println("SIGNED_PENDING_POSITIVE orders=2 wholeBatchOnce=true actualChildSources=true noAdmissionCapability=true unchangedParentAndChild=true");}
 static void trusted()throws Exception{Path d=Files.createTempDirectory("signed-pending-trust-");create(d,"TR","!$u seed(u)&&~blocked(u);");create(d,"TF","!@u seed(u)->ready(u);");for(boolean reverse:new boolean[]{false,true})try(Fixture f=new Fixture(d,"X"+reverse)){require(f.mind.compile("!anchor(1);",null,false),"trusted parent anchor");f.db.connectContext(reverse?"TF":"TR","own");f.db.connectContext(reverse?"TR":"TF","own");State parent=new State(f);Mind child=new Mind(f.mind);try{require(child.compile("!@u ready(u)->blocked(u);",null,false),"actual child uses both trusted members");Result r=f.db.inspectSignedPendingProduction(child,limits());require(r.status==Status.REFUTED&&!r.oppositions.isEmpty(),r.phase+": "+r.reason);require(r.foreign.size()==1&&r.foreign.get(0).members.size()==2&&r.foreign.get(0).trustedGroup.equals("own"),"one logical cut, BOTH physical original signed members");exact(f,r);for(Opposition o:r.oppositions)require(o.sources.size()==3&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==2,"both physical donor Sources plus actual child rule");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){f.db.applyConnectionCommand(f.mind,"TF","!private(9);");reject(()->lease.inspectSigned(limits()),"changed initialized shared member invalidates prior pending lease");}Result fresh=f.db.inspectSignedPendingProduction(child,limits());require(fresh.status==Status.REFUTED,"fresh full group still has real contradiction");exact(f,fresh);require(fresh.foreign.get(0).members.stream().anyMatch(v->v.initialization.size()==1),"actual new private member view, not old runtime facts");require(f.db.getRevision()==parent.revision&&inventory(f,f.mind).fingerprint.equals(parent.fingerprint),"private initialization and diagnostics do not publish parent");}finally{f.mind.release(child);}}
 System.out.println("SIGNED_PENDING_TRUSTED orders=2 bothPhysicalOrigins=true originalPinAndInitialization=true noFlattening=true");}
 static void ownership()throws Exception{Path d=Files.createTempDirectory("signed-pending-owner-");create(d,"A","!a(1);");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"parent anchor");f.db.connectContext("A");Mind child=new Mind(f.mind);try{require(child.compile("!$u prepared(u)&&~absent(u);",null,false),"signed child");ContextPendingProductionSnapshotSession closed=ContextPendingProductionSnapshotSession.open(f.db,child,64);closed.close();reject(()->closed.inspectSigned(limits()),"closed lease");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){boolean[] refused={false};Thread t=new Thread(()->{try{lease.qualifySigned(limits());}catch(Exception expected){refused[0]=true;}});t.start();t.join();require(refused[0],"owner thread required");require(child.compile("!changed(2);",null,false),"child changes");reject(()->lease.inspectSigned(limits()),"changed whole child fingerprint");}f.user.setCurrentMind(child);try{yes(f.db.inspectSignedPendingProduction(child,limits()));}finally{f.user.setCurrentMind(f.mind);}try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){require(f.mind.compile("!parentChanged(3);",null,false),"parent changes");reject(()->lease.inspectSigned(limits()),"changed parent fingerprint/revision");}}finally{f.mind.release(child);}reject(()->f.db.inspectSignedPendingProduction(child,limits()),"released child");Mind replacement=new Mind(f.mind);try{reject(()->f.db.inspectSignedPendingProduction(child,limits()),"released child cannot impersonate replacement");}finally{f.mind.release(replacement);}Mind first=new Mind(f.mind),second=new Mind(f.mind);try{reject(()->f.db.inspectSignedPendingProduction(first,limits()),"multiple root reservations");}finally{f.mind.release(second);}Mind nested=new Mind(first);try{reject(()->f.db.inspectSignedPendingProduction(first,limits()),"nested reservation");}finally{first.release(nested);f.mind.release(first);}reject(()->f.db.inspectSignedPendingProduction(f.mind,limits()),"settled parent is not proposed child");rollback(f);}
 System.out.println("SIGNED_PENDING_OWNERSHIP actualReservations=true retainedSignedRollbackNotImported=true actualRefreshOnly=true expiredAfterSettlement=true");}
 static void rollback(Fixture f)throws Exception{ContextNativePendingInspectionMatrix.command(f,"transaction start");Mind retained=(Mind)f.user.getCurrentMind();require(retained.query("!$u retainedOnly(u)&&~retainedAbsent(u);",null,false),"actual retained signed user child");long revision=f.db.getRevision();int[] calls={0};Mind[] actual={null};ContextPendingProductionSnapshotSession[] saved={null};IData proxy=(IData)java.lang.reflect.Proxy.newProxyInstance(DB.class.getClassLoader(),DB.class.getInterfaces(),(object,method,args)->{if(method.getName().equals("validateCommit")){synchronized(f.db){f.user.setData(f.db);try{Mind pending=(Mind)args[0];if(pending.getNext()==f.mind&&f.mind.requirePendingValidationChild(pending)!=null){++calls[0];actual[0]=pending;try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,pending,64)){Result r=lease.inspectSigned(limits());yes(r);require(r.proposed.fingerprint.equals(inventory(f,pending).fingerprint)&&!r.proposed.fingerprint.equals(inventory(f,retained).fingerprint),"ACTUAL rollback refresh target, not retained signed knowledge");require(retained.compile("!changedRetained(10);",null,false),"controlled retained sibling mutation");reject(()->lease.qualifySigned(limits()),"retained inventory freshness still mandatory");}saved[0]=ContextPendingProductionSnapshotSession.open(f.db,pending,64);yes(saved[0].inspectSigned(limits()));}f.db.validateCommit((IMind)args[0]);}finally{f.user.setData((IData)object);}}return null;}try{return method.invoke(f.db,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});f.user.setData(proxy);try{ContextNativePendingInspectionMatrix.command(f,"transaction rollback");}finally{f.user.setData(f.db);}require(calls[0]==1&&f.user.getCurrentMind()==f.mind&&f.db.getRevision()==revision,"actual rollback/refresh exactly once, no publication");require(inventory(f,f.mind).primary.stream().noneMatch(row->row.origin.contains("retainedOnly")||row.origin.contains("changedRetained")),"signed retained knowledge discarded, never imported");reject(()->saved[0].inspectSigned(limits()),"refresh lease expired after settlement");saved[0].close();reject(()->f.mind.requirePendingValidationChild(actual[0]),"rollback sibling scope cannot outlive settlement");}
 static Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 static Object replace(Object o,String name,Object value)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);Object old=f.get(o);f.set(o,value);return old;}
 static void refusal()throws Exception{Path d=Files.createTempDirectory("signed-pending-refusal-");create(d,"A","!$u seed(u)&&~blocked(u);");try(Fixture f=new Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"parent anchor");f.db.connectContext("A");State before=new State(f);ContextSignedPendingGuard.Evidence historical=null;Mind child=new Mind(f.mind);try{require(child.compile("!@u seed(u)->blocked(u);",null,false),"prepared conflict");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){ContextSignedCandidateInspection.Limits l=limits();ContextSignedPendingGuard.Result r=lease.qualifySigned(l);require(r.status==ContextSignedPendingGuard.Status.REFUTED&&r.evidence!=null&&!r.evidence.getOppositions().isEmpty(),r.phase+": "+r.reason);ContextSignedPendingGuard.Evidence e=r.evidence;historical=e;e.check(WORK,1);require(true,"fresh independent exact signed refutation audit capacity1");reject(()->e.check(1,64),"fresh audit budget");reject(()->e.getOppositions().clear(),"immutable opposition metadata");Object old=replace(e,"oppositions",Collections.emptyList());reject(()->e.check(WORK,64),"lost complete opposition metadata");replace(e,"oppositions",old);Opposition summary=e.getOppositions().get(0);old=replace(summary,"depth",summary.depth+1);reject(()->e.check(WORK,64),"forged grade summary");replace(summary,"depth",old);Object branch=field(e,"branch"),receiver=field(branch,"initialRejection");Map<?,?> all=(Map<?,?>)field(receiver,"checks");Object proofResult=all.values().stream().filter(v->{try{return !((List<?>)field(v,"emptyProofs")).isEmpty();}catch(Exception ex){throw new RuntimeException(ex);}}).findFirst().get();old=replace(proofResult,"emptyProofs",Collections.emptyList());reject(()->e.check(WORK,64),"actual proof roots cannot be replaced by scalar opposition metadata");replace(proofResult,"emptyProofs",old);e.check(WORK,1);require(true,"restored owned proof graph freshly checks");ContextSignedCandidateInspection.Limits tiny=new ContextSignedCandidateInspection.Limits(64,8,2,16,WORK,500000,WORK,1,64);ContextSignedPendingGuard.Result unverified=lease.qualifySigned(tiny);require(unverified.status==ContextSignedPendingGuard.Status.INCOMPLETE&&unverified.evidence==null&&unverified.phase.equals("signed-refutation-audit"),"unverified real conflict exposes no sealed proof prefix");Result no=lease.inspectSigned(tiny);require(no.status==Status.INCOMPLETE&&no.proposed==null&&no.foreign.isEmpty()&&no.oppositions.isEmpty(),"facade also has no provisional view/opposition prefix");reject(()->lease.inspectSigned(new ContextSignedCandidateInspection.Limits(63,8,2,16,WORK,500000,WORK,WORK,64)),"exact lease row policy");lease.requireCurrent();before.unchanged(f);require(true,"all proof checks/refusals read-only and lease remains current");}}finally{f.mind.release(child);}historical.check(WORK,1);require(true,"historical detached proof still audits after child release, never live authority");Mind bad=new Mind(f.mind);try{require(bad.compile("!@u p(u)||q(u);",null,false),"actual unsupported whole row");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,bad,64)){ContextSignedPendingGuard.Result unsupported=lease.qualifySigned(limits());require(unsupported.status==ContextSignedPendingGuard.Status.INCOMPLETE&&unsupported.evidence==null,"unsupported child cannot expose partial signed refusal");}}finally{f.mind.release(bad);}reject(()->f.db.inspectSignedPendingProduction(f.mind,limits()),"actual child required");}
 System.out.println("SIGNED_PENDING_REFUSAL fullProofLedgerNotSummary=true independentFreshAudit=true metadataAndGraphTamperRejected=true incompleteNoPrefix=true");}
}
